insert into public.panda_records(kind,id,data) values('programs','plan_strength','{"id":"plan_strength","name":"12 Week Strength Foundation","weeks":12,"status":"published","version":1,"origin":"Illustrative plan using the GYM PLAN and CORE sheet structure. Coach review required.","goal":"Build a repeatable strength routine","description":"Four training days with a balanced push, pull, legs and upper split. Review the assigned prescriptions before training; share how the week went at your check-in.","notes":"Warm-up and working-load choices are agreed with your coach. Stop a movement that causes pain and report the issue. No live workout logging is required.","sessions":[{"id":"push","name":"Push · Chest, shoulders & triceps","day":"Monday","focus":"Upper-body pressing","image":"assets/equipment.webp","exercises":[{"exercise_id":"ex_0b0f76e0ce35","sets":3,"reps":"6–8","load":"Example: 60 kg","rest":90,"tempo":"Controlled","notes":"Controlled movement. Follow the exercise setup cue."},{"exercise_id":"ex_9f54be219301","sets":3,"reps":"8–12","load":"Coach-selected load","rest":90,"tempo":"Controlled","notes":"Controlled movement. Follow the exercise setup cue."},{"exercise_id":"sheet_42c9ccbfcd1b","sets":3,"reps":"8–12","load":"Coach-selected load","rest":90,"tempo":"Controlled","notes":"Controlled movement. Follow the exercise setup cue."},{"exercise_id":"sheet_b893058848d8","sets":3,"reps":"8–12","load":"Coach-selected load","rest":90,"tempo":"Controlled","notes":"Controlled movement. Follow the exercise setup cue."},{"exercise_id":"ex_demo_cable_pushdown","sets":3,"reps":"10–15","load":"Coach-selected load","rest":90,"tempo":"Controlled","notes":"Controlled movement. Follow the exercise setup cue."}]},{"id":"pull","name":"Pull · Back & biceps","day":"Tuesday","focus":"Rows, pulls and arms","image":"assets/equipment.webp","exercises":[{"exercise_id":"ex_90996efb6be9","sets":3,"reps":"8–12","load":"Coach-selected load","rest":90,"tempo":"Controlled","notes":"Controlle