insert into public.panda_records(kind,id,data) values('programs','plan_core','{"id":"plan_core","name":"Core & Activity Reference","weeks":4,"status":"published","version":1,"origin":"Demo content based on the CORE and ACTIVITY template fields.","goal":"A simple reference for core work and activity","description":"A core circuit to discuss with your coach, with separate step/cardio targets in the activity page.","notes":"The time values are written prescriptions, not a countdown timer.","sessions":[{"id":"core","name":"Core · Stability circuit","day":"Wednesday","focus":"Three controlled rounds","image":"assets/equipment.webp","exercises":[{"exercise_id":"sheet_0e0d7ea0396e","sets":3,"reps":"8 per side","load":"Bodyweight","rest":45,"tempo":"Controlled","notes":"Controlled movement. Follow the exercise setup cue."},{"exercise_id":"sheet_4d6b050611f7","sets":3,"reps":"20–30 sec / side","load":"Bodyweight","rest":45,"tempo":"Controlled","notes":"Controlled movement. Follow the exercise setup cue."},{"exercise_id":"sheet_6a7de7eec914","sets":3,"reps":"10 per side","load":"Light, controlled","rest":45,"tempo":"Controlled","notes":"Controlled movement. Follow the exercise setup cue."}]}],"versions":[]}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('nutrition_plans','nutrition_balanced','{"id":"nutrition_balanced","name":"Panda Nutrition Strategy","status":"published","version":1,"origin":"Completed demo meal plan; sheet food values are imported and require coach verification.","targets":{"calories":2200,"protein":160,"carbs":230,"fat":69,"fiber":30,"water":3},"notes":"Illustrative targets, not an individual recommendation. Planned meal totals are shown separately so your coach can identify and adjust any gap.","variants":[{"id":"training-day","name":"Training day","meals":[{"id":"breakfast","name":"Breakfast · Oats & yoghurt","time":"07:30","image":"assets/meals/training-day-breakfast.webp","items":[{"food_id":"food_61","quantity":60},{"food_id":"food_69","quantity":200},{"food_id":"food_118","quantity":1}],"instructions":"Prepare the oats with water; serve the yoghurt and banana alongside. Weigh oats dry."},{"id":"lunch","name":"Lunch · Chicken & rice","time":"12:30","image":"assets/meals/training-day-lunch.webp","items":[{"food_id":"food_19","quantity":180},{"food_id":"food_48","quantity":85},{"food_id":"food_125","quantity":100}],"instructions":"Weigh the rice uncooked. Prepare and portion the chicken and vegetables consistently. Season to preference."},{"id":"snack","name":"Snack · Yoghurt & almonds","time":"16:00","image":"assets/meals/training-day-snack.webp","items":[{"food_id":"food_69","quantity":200},{"food_id":"food_92","quantity":20}],"instructions":"Serve the yoghurt with the weighed almonds. Report any food preference or allergy before using this example."},{"id":"dinner","name":"Dinner · Salmon & sweet potato","time":"19:30","image":"assets/meals/training-day-dinner.webp","items":[{"food_id":"food_23","quantity":180},{"food_id":"food_46","quantity":250},{"food_id":"food_125","quantity":100}],"instructions":"Prepare the salmon and sweet potato and serve with vegetables. The photograph is a serving illustration."}]},{"id":"rest-day","name":"Rest day","meals":[{"id":"breakfast","name":"Breakfast · Oats & yoghurt","time":"07:30","image":"assets/meals/rest-day-breakfast.webp","items":[{"food_id":"food_61","quantity":60},{"food_id":"food_69","quantity":200},{"food_id":"food_118","quantity":1}],"instructions":"Prepare the oats with water; serve the yoghurt and banana alongside. Weigh oats dry."},{"id":"lunch","name":"Lunch · Chicken & rice","time":"12:30","image":"assets/meals/rest-day-lunch.webp","items":[{"food_id":"food_19","quantity":180},{"food_id":"food_48","quantity":68},{"food_id":"food_125","quantity":100}],"instructions":"Weigh the rice uncooked. Prepare and portion the chicken and vegetables consistently. Season to preference."},{"id":"snack","name":"Snack · Yoghurt & almonds","time":"16:00","image":"assets/meals/rest-day-snack.webp","items":[{"food_id":"food_69","quantity":200},{"food_id":"food_92","quantity":20}],"instructions":"Serve the yoghurt with the weighed almonds. Report any food preference or allergy before using this example."},{"id":"dinner","name":"Dinner · Salmon & sweet potato","time":"19:30","image":"assets/meals/rest-day-dinner.webp","items":[{"food_id":"food_23","quantity":180},{"food_id":"food_46","quantity":200},{"food_id":"food_125","quantity":100}],"instructions":"Prepare the salmon and sweet potato and serve with vegetables. The photograph is a serving illustration."}]},{"id":"higher-carb-day","name":"Higher-carb day","meals":[{"id":"breakfast","name":"Breakfast · Oats & yoghurt","time":"07:30","image":"assets/meals/higher-carb-day-breakfast.webp","items":[{"food_id":"food_61","quantity":60},{"food_id":"food_69","quantity":200},{"food_id":"food_118","quantity":1}],"instructions":"Prepare the oats with water; serve the yoghurt and banana alongside. Weigh oats dry."},{"id":"lunch","name":"Lunch · Chicken & rice","time":"12:30","image":"assets/meals/higher-carb-day-lunch.webp","items":[{"food_id":"food_19","quantity":180},{"food_id":"food_48","quantity":98},{"food_id":"food_125","quantity":100}],"instructions":"Weigh the rice uncooked. Prepare and portion the chicken and vegetables consistently. Season to preference."},{"id":"snack","name":"Snack · Yoghurt & almonds","time":"16:00","image":"assets/meals/higher-carb-day-snack.webp","items":[{"food_id":"food_69","quantity":200},{"food_id":"food_92","quantity":20}],"instructions":"Serve the yoghurt with the weighed almonds. Report any food preference or allergy before using this example."},{"id":"dinner","name":"Dinner · Salmon & sweet potato","time":"19:30","image":"assets/meals/higher-carb-day-dinner.webp","items":[{"food_id":"food_23","quantity":180},{"food_id":"food_46","quantity":288},{"food_id":"food_125","quantity":100}],"instructions":"Prepare the salmon and sweet potato and serve with vegetables. The photograph is a serving illustration."}]}],"versions":[]}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('articles','welcome','{"id":"welcome","category":"Getting started","title":"Your portal, your plan","summary":"Know where to find your plans and how to keep your coach informed.","image":"assets/education/education-welcome.webp","sections":[["Your home base","Your dashboard brings together the plan assigned to you, your nutrition strategy and your next check-in. Open the reference you need, then return when you have feedback to share."],["Before you begin","Check your profile, goals, availability, food preferences and any limitations with your coach. Read the coaching guidelines and the current version of each assigned plan."],["Keep the feedback useful","A short specific note about training, meals or recovery helps your coach make the next adjustment. You do not need to enter every set during your training."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('articles','plans','{"id":"plans","category":"Training","title":"Read your training plan","summary":"Understand the difference between a prescription and feedback.","image":"assets/education/education-plans.webp","sections":[["Read the full day","Review the exercise order, sets, repetition range, written rest guidance and coach notes. Any sample working load is a plan example, not a required starting weight."],["Exercise references","Open the linked exercise to see its muscle targets, equipment and catalogue cue. Each photograph illustrates its linked exercise. Read the written cue and ask your coach to confirm your setup."],["Changes and questions","Tell your coach about unavailable equipment, discomfort or a schedule change. The coach can publish a new plan version while your earlier check-ins remain in the history."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('articles','nutrition','{"id":"nutrition","category":"Nutrition","title":"Make your meal plan practical","summary":"Portions, reference units and preparation all matter.","image":"assets/education/education-nutrition.webp","sections":[["Understand the reference","Some foods are listed per 100 grams, others per egg, packet or tablespoon. The quantity in your meal uses the same unit. Rice labelled uncooked is weighed before cooking."],["Plan total versus target","The planned meal total is calculated from the ingredients. The coach target is shown separately. A difference is visible so the plan can be adjusted rather than hidden."],["Bring practical feedback","Tell your coach which meals suit your routine, which ingredients are unavailable and what you would like to swap. Check allergies and preferences before following a new plan."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('articles','swaps','{"id":"swaps","category":"Nutrition","title":"Food swaps with context","summary":"Matching one nutrient does not make two foods identical.","image":"assets/education/education-swaps.webp","sections":[["Use a confirmed swap","The swap guide matches a chosen nutrient using the reference portions. Protein-equivalent servings can have different calories, fats and food volumes."],["Keep preparation consistent","Use the preparation state and portion unit written in the plan. A dry rice serving and a cooked rice serving cannot be exchanged gram for gram."],["Ask for an alternative","Report availability, preferences or digestion issues in your check-in. Your coach decides whether to change the food, portion or full meal."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('articles','checkin','{"id":"checkin","category":"Coaching","title":"A useful weekly check-in","summary":"Give your coach the context behind the numbers.","image":"assets/education/education-checkin.webp","sections":[["Review the week","Consider training frequency, nutrition adherence, energy, sleep, hunger and digestion. An honest incomplete week is more useful than an invented perfect week."],["Describe one example","Say what made a meal difficult or why a training day moved. Include changes to schedule, travel or equipment where relevant."],["Submit and review","Save a draft if you need more time. Once submitted, your coach can review the entry and leave feedback alongside your original answers."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('articles','measure','{"id":"measure","category":"Progress","title":"Measure consistently","summary":"Make comparisons meaningful by keeping the method stable.","image":"assets/education/education-measure.webp","sections":[["Record the context","Use the same unit and note the date. Where possible, keep the measurement conditions consistent and tell your coach when a method changes."],["Missing is not zero","Leave an unknown measurement blank. The portal keeps missing values separate from real readings and plots only values that were entered."],["Photographs","Use comparable pose, distance, lighting and clothing for private progress references. Uploaded photographs are saved privately in your coaching account."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('articles','recovery','{"id":"recovery","category":"Recovery","title":"Recovery belongs in the conversation","summary":"Describe life outside the training plan.","image":"assets/education/education-recovery.webp","sections":[["Energy and sleep","Your check-in includes both hours of sleep and a quality rating. They describe different parts of the week and help provide context."],["Changing routines","Travel, work patterns and unusual fatigue can affect how manageable a plan feels. Share those changes rather than silently changing every target."],["Plan with your coach","Training and rest days are part of the assigned programme. Any change to frequency or intensity should be discussed through the coaching review."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('articles','shopping','{"id":"shopping","category":"Nutrition","title":"Prepare a useful shopping list","summary":"Turn your assigned meals into quantities you can check.","image":"assets/education/education-shopping.webp","sections":[["Choose a day variant","The grocery list uses the selected training, rest or higher-carb day. Repeating it across a week is a planning aid, not an automatic mixed-week menu."],["Check what you already have","Combined quantities keep each food’s reference unit. Review package sizes, fresh food storage and your schedule before buying."],["Simple preparation","Group meals with shared ingredients and note which quantities are raw or cooked. Keep oils, dressings and add-ons consistent with your plan."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('articles','travel','{"id":"travel","category":"Lifestyle","title":"Eating out and travel","summary":"Take your plan into the real world.","image":"assets/education/education-travel.webp","sections":[["Plan ahead","Discuss regular restaurant meals, travel and food availability with your coach. Agree on flexible meal choices rather than guessing exact macros for every unfamiliar dish."],["Keep a short note","Describe the meal and the context in your nutrition feedback. Use an estimate only if your coach has asked for one."],["Return to your routine","A changed meal is useful information for the next adjustment. Review what was manageable and prepare the next planned meal."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('articles','guidelines','{"id":"guidelines","category":"Coaching","title":"Coaching guidelines","summary":"A clear working agreement for both sides.","image":"assets/education/education-guidelines.webp","sections":[["Your part","Keep profile information current, read your assigned plans, submit the agreed check-in and raise questions or problems promptly."],["Your coach’s part","Your coach sets targets, reviews feedback, approves exercise and food references, and publishes changes to your assigned plans."],["Support","Use the contact details your coach provides. This portal does not contain chat, payments, live training monitoring or video calls."]],"status":"published","version":1,"origin":"Released demo editorial content","attachment":null}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('settings','brand','{"name":"TRAIN WITH PANDA","coach":"Panda Coach","contact":"Ask your coach for their preferred contact details.","currency":"AED"}'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('settings','strategy','[["Client profile","Your goal, current and target weight, age, activity, preferences and limitations inform the coach’s plan. Review these in My profile."],["Calories & macros","The coach sets calorie, protein, carbohydrate and fat targets. Meal totals are calculated separately from reference foods. Fibre and water targets are shown when assigned."],["Meal structure","Each meal has a timing label, food list, exact reference quantities and calculated nutrient totals."],["Food quality & selection","The food library retains the source categories: proteins, carbohydrates, fats, vegan/vegetarian and fruits/vegetables/snacks. Your coach chooses suitable ingredients."],["Food swap guide","Use the nutrient-based examples below and confirm substitutions with your coach. Matching protein or carbohydrates alone does not match every nutrient."],["Training & rest days","Choose the appropriate assigned day variant. A higher-carb variant is a planning example; its use and frequency require coach approval."],["Pre / post training","Your coach can place meals around the training time that works for you. Report food tolerance and practicality in your weekly feedback."],["Hydration & electrolytes","Follow the water target assigned in your plan. Electrolyte requirements and changes for travel or heat should be discussed with your coach. No automatic electrolyte prescription is made here."],["Supplement protocol","Review name, assigned dose, timing, purpose and notes in Supplements. Only use a protocol that your coach has confirmed for you."],["Weekly adjustments","Weight, waist, hunger, energy, sleep, digestion and adherence are reviewed together. Targets change through a published coach plan update, not automatically."],["Higher-carb strategy","The optional day variant shows how meals can differ. Timing, frequency and suitability are a coach decision."],["Eating out & travel","Discuss restaurant meals and travel in advance. Keep useful notes about availability and adherence rather than treating estimates as exact values."],["Grocery list","Build a combined list from the selected day variant, retaining grams, millilitres and count-based portions."],["Client guidelines","Keep portion methods consistent, follow the agreed targets, and report issues at check-in. Do not treat the example data in this demo as a personalised prescription."]]'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('settings','roadmap','[{"id":"phase1","title":"Set your foundation","weeks":"Weeks 1–2","text":"Complete your profile, agree on goals, review your plans and establish the weekly check-in routine."},{"id":"phase2","title":"Build consistency","weeks":"Weeks 3–6","text":"Follow the agreed structure, identify practical obstacles and use check-ins to improve how the plan fits your life."},{"id":"phase3","title":"Review and refine","weeks":"Weeks 7–10","text":"Compare dated progress, review feedback and discuss targeted training or nutrition adjustments."},{"id":"phase4","title":"Plan the next chapter","weeks":"Weeks 11–12","text":"Reflect on your results and habits, then agree on the next phase with your coach."}]'::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) values('settings','swaps','[{"id":"swap_protein","from":"food_19","to":"food_21","basis":"protein","note":"Example matched on protein only; calories, fat and portions differ."},{"id":"swap_carb","from":"food_48","to":"food_46","basis":"carbs","note":"Example matched on carbohydrate; rice quantity is its uncooked weight."}]'::jsonb) on conflict(kind,id) do nothing;
